class rx_payload_body_c extends uvm_object;

    // constructor
    function new(string name = "");
        super.new(name);
    endfunction

    // ------------------------------------------------------------
    // RXD payload (dynamic array), generated by sequence layer
    // ------------------------------------------------------------
    rand bit [7:0] rxd_payload[];

    // ------------------------------------------------------------
    // Constraints
    // 1) payload size between 1 and 1023 bytes
    // 2) each byte value range 0~255
    // ------------------------------------------------------------
    constraint size_c {
        rxd_payload.size() inside {[1:1023]};
    }

    constraint value_c {
        foreach (rxd_payload[i]) rxd_payload[i] inside {[0:255]};
    }

    // ------------------------------------------------------------
    // Optional: print helper
    // ------------------------------------------------------------
    virtual function string convert2string();
        string s;
        s = $sformatf("payload_size=%0d", rxd_payload.size());
        if (rxd_payload.size() > 0) begin
            // ?ªç°¡?®å??ºå?å¹¾å€‹ï??¿å? log å¤ªé•·
            int unsigned n;
            n = (rxd_payload.size() < 16) ? rxd_payload.size() : 16;
            s = {s, " payload[0..", $sformatf("%0d", n-1), "]="};
            for (int i = 0; i < n; i++) begin
                s = {s, $sformatf(" %02h", rxd_payload[i])};
            end
            if (rxd_payload.size() > n) s = {s, " ..."};
        end
        return s;
    endfunction

    // ------------------------------------------------------------
    // Factory registration + field automation
    // ------------------------------------------------------------
    `uvm_object_utils_begin(rx_payload_body_c)
        `uvm_field_array_int(rxd_payload, UVM_DEFAULT)
    `uvm_object_utils_end

endclass